#include <stdint.h>

typedef struct {
    uint32_t codepoint;
    uint32_t bitmap_offset;
    uint8_t width;
    uint8_t height;
    int8_t bearing_x;
    int8_t bearing_y;
    uint8_t advance;
} font_glyph_t;

typedef struct {
    const uint8_t *bitmaps;
    const font_glyph_t *glyphs;
    uint16_t glyph_count;
    uint8_t height;
    uint8_t ascender;
} font_info_t;

